INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28DVZB8', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if accurately cited, would best support the claim that Adichie''s novel challenges the single-story framework?', E'In her 2013 novel Americanah, Chimamanda Ngozi Adichie portrays the experiences of Ifemelu, a Nigerian woman navigating racial identity in the United States and then returning to a rapidly modernizing Lagos. Literary scholars have argued that the novel challenges what Adichie herself has called the ''single story'' — the tendency of Western media to reduce African nations to monolithic narratives of poverty and conflict. By depicting Lagos as a city of ambitious entrepreneurs, vibrant cultural production, and sharp class divisions, the novel insists on a complexity that the single-story framework cannot accommodate.', $lyceon_json$[{"key":"A","text":"\"Adichie's Lagos chapters are notable for their refusal to flatten the city into either a site of despair or an uncritical success story, instead rendering its contradictions with granular specificity.\""},{"key":"B","text":"\"The novel's American sections are its strongest, offering a sustained critique of racial categorization that resonates with the broader African American literary tradition established by writers such as Baldwin and Ellison.\""},{"key":"C","text":"\"Americanah is ultimately a romance novel whose love plot overshadows its sociopolitical commentary, leaving the reader with emotional satisfaction rather than intellectual provocation.\""},{"key":"D","text":"\"Adichie's prose style draws heavily on the oral storytelling traditions of Igbo culture, creating a narrative voice that is distinctive among contemporary Anglophone African novelists writing about migration and displacement.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The passage claims Adichie''s novel challenges the single-story framework by depicting Lagos with complexity rather than reducing it to a monolithic narrative. The quotation about Adichie''s Lagos chapters refusing to flatten the city and rendering its contradictions with specificity directly supports that claim. The quotation praising the American sections and linking them to the African American literary tradition addresses a different aspect of the novel and does not speak to the single-story challenge regarding Africa. The quotation characterizing the novel as primarily a romance whose love plot overshadows sociopolitical commentary contradicts rather than supports the claim. The quotation about Igbo oral storytelling traditions discusses narrative style and voice rather than the novel''s engagement with reductive portrayals of African nations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28OAUMX', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from the study, if accurate, would most directly undermine the hypothesis that mycorrhizal networks facilitate resource sharing between established trees and seedlings?', E'Forest ecologists have long hypothesized that mycorrhizal fungal networks — underground webs of fungal hyphae connecting the roots of neighboring trees — enable established trees to transfer carbon and mineral nutrients to nearby seedlings, thereby improving seedling survival in shaded understory conditions. A team at the University of British Columbia designed a field experiment to test this hypothesis by tracking isotopically labeled carbon through putative network connections in a temperate rainforest dominated by Douglas fir.', $lyceon_json$[{"key":"A","text":"Seedlings physically separated from mycorrhizal connections by fine-mesh barriers showed survival rates and growth increments indistinguishable from connected seedlings"},{"key":"B","text":"The isotopically labeled carbon appeared in seedling tissues within seventy-two hours, a transfer rate faster than any previously documented mycorrhizal nutrient exchange in temperate forest systems"},{"key":"C","text":"Douglas fir seedlings in the study area formed associations predominantly with ectomycorrhizal fungi of the genus Rhizopogon, a genus known to form extensive hyphal networks spanning dozens of meters"},{"key":"D","text":"Established Douglas fir trees allocated a greater proportion of their total photosynthate to root-associated fungi during the autumn months, precisely when seedling demand for supplemental carbon would be expected to peak under conditions of reduced light availability in the understory canopy"}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis holds that mycorrhizal networks improve seedling survival by transferring resources from established trees. If seedlings severed from all mycorrhizal connections survived and grew at the same rates as connected seedlings, then the network confers no detectable benefit, directly undermining the hypothesis. The finding about rapid carbon transfer would actually support the hypothesis by confirming that labeled carbon moves through the network to seedlings quickly. The finding about Rhizopogon fungi forming extensive networks describes the physical infrastructure that could enable sharing but says nothing about whether sharing actually benefits seedlings. The finding about seasonal allocation patterns in established trees is consistent with the hypothesis rather than undermining it, since increased photosynthate allocation to fungi during periods of high seedling need would suggest facilitation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28W2A9I', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Ethnomusicologist Ravi Johal argues that the rhythmic structures of Carnatic music influenced early jazz improvisation — a claim that, while provocative, has gained traction among scholars who study cross-cultural musical _______ Johal points to specific ragas whose polyrhythmic patterns appear in recordings made by New Orleans brass bands between 1911 and 1928.', $lyceon_json$[{"key":"A","text":"exchange. Johal"},{"key":"B","text":"exchange; and Johal"},{"key":"C","text":"exchange, Johal"},{"key":"D","text":"exchange Johal"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses meet at the blank. The first clause, which includes a parenthetical em-dash aside, ends with ''cross-cultural musical exchange.'' The second independent clause begins with ''Johal points to specific ragas...'' A period correctly separates these two complete sentences. The option using only a comma (''exchange, Johal'') creates a comma splice — two independent clauses joined by a comma with no coordinating conjunction. The option omitting all punctuation (''exchange Johal'') creates a run-on sentence. The option using a semicolon followed by ''and'' (''exchange; and Johal'') is redundant: a semicolon already functions as a clause separator, so adding the conjunction ''and'' is non-standard. The difficulty here lies in tracking the first clause''s structure through the em-dash interruption to recognize that both sides of the blank are full independent clauses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29N3MA8', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists at the Galway Oceanographic Institute hypothesized that the bioluminescent displays of the deep-sea shrimp Systellaspis debilis serve primarily as a predator-deterrent mechanism rather than as a mate-attraction signal. They noted that the shrimp''s light-producing organs are positioned along the ventral surface, directing luminescence downward — an orientation poorly suited to signaling conspecifics in the water column above.', $lyceon_json$[{"key":"A","text":"S. debilis individuals that had their ventral photophores experimentally blocked were captured by predators at significantly higher rates than unblocked controls"},{"key":"B","text":"Several other deep-sea crustacean species found in the same habitat range use bioluminescence exclusively during their reproductive mating seasons, suggesting a conserved signaling function across taxa"},{"key":"C","text":"The chemical composition of the luciferin used by S. debilis is identical to that found in unrelated bioluminescent fish species"},{"key":"D","text":"S. debilis populations in the eastern Atlantic have photophore counts that vary with depth but not with population density of potential mates"}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis claims that bioluminescence in S. debilis deters predators. A finding that shrimp whose photophores were blocked suffered higher predation directly demonstrates a causal link between the luminescent display and predator avoidance, supporting the hypothesis. The finding about other crustaceans using bioluminescence during mating seasons concerns different species and a different function, so it does not bear on S. debilis''s predator deterrence. The finding about identical luciferin chemistry addresses biochemistry shared across taxa, which is irrelevant to the functional purpose of S. debilis''s displays. The finding about photophore counts varying with depth but not mate density is only indirectly suggestive and does not establish that the displays deter predators.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29Q2JV3', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'A recent survey of municipal composting programs found that cities providing curbside collection bins _______ significantly higher participation rates than those requiring residents to transport organic waste to centralized drop-off facilities, a finding that reinforces arguments for convenience-driven infrastructure in waste reduction policy.', $lyceon_json$[{"key":"A","text":"has consistently reported"},{"key":"B","text":"having consistently reported"},{"key":"C","text":"consistently reporting"},{"key":"D","text":"consistently reported"}]$lyceon_json$::jsonb, 'D', NULL, E'The sentence requires a finite verb for the clause beginning with ''cities providing curbside collection bins.'' The subject ''cities'' is plural, and the blank must supply the main verb of the subordinate clause introduced by ''that.'' The option ''consistently reported'' provides a finite past-tense verb in the plural form that agrees with ''cities'' and fits the past-tense framing of the survey''s findings (''A recent survey...found that cities...reported''). The option ''has consistently reported'' uses a singular verb (''has'') that does not agree with the plural subject ''cities.'' The option ''having consistently reported'' is a participial phrase that creates a sentence fragment — the clause ''that cities providing curbside collection bins having consistently reported...'' lacks a finite verb. The option ''consistently reporting'' is likewise a present participle that cannot serve as the main verb of the clause, leaving the ''that'' clause without a finite verb and producing a fragment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AHKAWQ', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "plastic" most nearly mean?', E'Neuroscientist Rina Okafor''s 2019 study demonstrated that the adult hippocampus remains remarkably <u>plastic</u>, generating new neurons well past the age of seventy in participants who maintained cognitively demanding routines. This finding challenged the longstanding assumption that neural architecture becomes essentially fixed after adolescence.', $lyceon_json$[{"key":"A","text":"composed of synthetic polymer materials"},{"key":"B","text":"superficially convincing but ultimately artificial"},{"key":"C","text":"capable of being reshaped or reorganized"},{"key":"D","text":"rigid enough to preserve its original configuration"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage states that the hippocampus generates new neurons past age seventy and that this challenges the assumption of fixed neural architecture, directly indicating that the brain can be reshaped. The choice "capable of being reshaped or reorganized" captures this meaning of adaptability. The choice "composed of synthetic polymer materials" applies the common everyday meaning of "plastic" as a manufactured substance, which is irrelevant in a neuroscience context. The choice "superficially convincing but ultimately artificial" introduces a connotation of deception that nothing in the passage supports. The choice "rigid enough to preserve its original configuration" directly contradicts the passage, which argues against the idea of fixedness.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BGOHK3', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Paleontologist Rina Okamoto has proposed that the massive cranial crests of certain pterosaur species, such as Tupuxuara leonardii, functioned primarily as thermoregulatory structures rather than as sexual display organs. Okamoto notes that the internal architecture of the crests contains a dense network of vascular channels, a feature consistent with heat dissipation but unnecessary for visual signaling. She acknowledges, however, that among extant vertebrates, structures originally selected for thermoregulation — such as the oversized ears of fennec foxes — frequently acquire secondary signaling functions over evolutionary time. If Okamoto''s thermoregulatory hypothesis is correct, then the crests ________', $lyceon_json$[{"key":"A","text":"may well have come to serve a display function also, but that role would have been derivative rather than the original selective pressure shaping crest evolution."},{"key":"B","text":"could not have played any role in mate selection, since thermoregulatory and display functions are physiologically incompatible within a single anatomical structure."},{"key":"C","text":"would have been reduced in size over successive generations as pterosaurs migrated to cooler climates where heat dissipation was no longer advantageous."},{"key":"D","text":"must have appeared only in pterosaur species inhabiting equatorial regions, where the selective advantage of enhanced heat dissipation would have been greatest among all known flying reptiles of the Mesozoic era."}]$lyceon_json$::jsonb, 'A', NULL, E'Okamoto hypothesizes that the crests evolved primarily for thermoregulation but acknowledges that thermoregulatory structures in living vertebrates often acquire secondary signaling functions. The logical completion is that the crests may also have served a display function, but that function would have been secondary to the original thermoregulatory purpose. The choice ruling out any role in mate selection contradicts Okamoto''s own acknowledgment that thermoregulatory structures frequently gain signaling functions, and the claim of physiological incompatibility is unsupported. The choice predicting size reduction in cooler climates introduces an evolutionary trajectory the passage does not discuss and assumes a simple relationship between climate and crest size. The choice restricting crests to equatorial species makes an absolute geographic claim the passage does not support and ignores the possibility that thermoregulation could be advantageous in varied climates.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C23Z55', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 2 most likely characterize the reasoning presented in Text 1?', E'Text 1:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CVGEM4', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason the researchers give for the discrepancy between laboratory and field measurements of soil carbon?', E'A 2023 study led by geochemist Priya Narayanan compared laboratory-derived estimates of soil carbon sequestration rates with field measurements taken across seventeen boreal forest sites in northern Manitoba. The laboratory analyses, which involved drying and sieving soil samples before combustion testing, consistently yielded sequestration estimates twenty-three to thirty-one percent higher than those obtained from in situ gas-flux monitoring. Narayanan''s team attributed the gap primarily to the loss of volatile organic compounds during sample preparation: heating the samples drove off carbon-containing gases that would have remained in the soil under natural conditions, inflating the apparent carbon content of the remaining solid material.', $lyceon_json$[{"key":"A","text":"Field instruments in boreal forests are frequently miscalibrated due to temperature fluctuations that distort gas-flux readings"},{"key":"B","text":"Sample preparation procedures expel volatile carbon compounds, causing lab analyses to overstate the carbon present in undisturbed soil"},{"key":"C","text":"Boreal forest soils contain unusually high concentrations of mineral carbon that laboratory combustion tests cannot distinguish from organic carbon"},{"key":"D","text":"The seventeen sites chosen for the study were unrepresentative of broader boreal forest conditions, skewing the field data downward relative to laboratory baselines"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage explicitly states that Narayanan''s team attributed the discrepancy to the loss of volatile organic compounds during sample preparation, which inflated the apparent carbon content in lab results. The choice about sample preparation expelling volatile carbon compounds directly restates this explanation. The choice about miscalibrated field instruments invents a problem the passage does not mention. The choice about mineral carbon introduces a distinction between mineral and organic carbon that the passage never discusses. The choice about unrepresentative sites contradicts the passage, which presents the seventeen sites without suggesting they were poorly chosen.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DW3WOD', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1987, archaeologist Priya Venkatesh discovered fragments of a clay tablet near the banks of the Kaveri _______ inscribed with symbols that bore no resemblance to any known Dravidian script, the fragments prompted a wholesale reexamination of the region''s linguistic history.', $lyceon_json$[{"key":"A","text":"River, inscribed"},{"key":"B","text":"River. Inscribed"},{"key":"C","text":"River; inscribed"},{"key":"D","text":"River, and inscribed"}]$lyceon_json$::jsonb, 'B', NULL, E'The text after the blank contains a participial phrase (''inscribed with symbols that bore no resemblance to any known Dravidian script'') modifying ''the fragments,'' followed by the main clause (''the fragments prompted a wholesale reexamination''). A period after ''River'' correctly ends the first sentence and begins a new sentence with the participial phrase attached to its subject. The option using a comma alone (''River, inscribed'') creates a comma splice because the second portion, once the participial phrase concludes, contains a full independent clause (''the fragments prompted...''). The option using a semicolon (''River; inscribed'') is incorrect because what follows the semicolon is not an independent clause on its own — it begins with a participial phrase, not a subject-verb unit. The option using ''and inscribed'' creates a faulty coordination because ''inscribed'' is a participle, not a verb parallel to ''discovered.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F3ZILA', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the two proposed highway routes would both reduce commute times for residents of the outer suburbs, transportation planner Kenji Matsuda recommends the northern corridor because it _______ fewer acres of protected wetland than the southern alternative would.', $lyceon_json$[{"key":"A","text":"would have disrupted"},{"key":"B","text":"will have disrupted"},{"key":"C","text":"would disrupt"},{"key":"D","text":"had disrupted"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence describes a hypothetical scenario: a recommendation about a proposed future action. The clause structure uses the conditional ''would'' to express what the northern corridor hypothetically does compared to the southern alternative. The simple conditional ''would disrupt'' correctly matches the hypothetical framing established by ''recommends'' and is parallel to ''would'' later in the sentence (''than the southern alternative would''). The option ''would have disrupted'' uses the past conditional, implying a completed hypothetical action in the past, which does not match the forward-looking context of a recommendation about a proposed route. The option ''will have disrupted'' uses the future perfect, which implies certainty about a completed future action and clashes with the hypothetical framing. The option ''had disrupted'' uses the past perfect, implying a completed past action, which is inconsistent with the proposed and not-yet-built nature of the routes.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 65, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G4YELJ', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Tardigrades, microscopic animals sometimes called water bears, are among the most resilient organisms known to science. Researchers at the University of Stuttgart subjected tardigrades to temperatures as low as negative 272 degrees Celsius for extended periods and found that the creatures entered a state of cryptobiosis, suspending all metabolic processes. Upon rewarming, ninety-one percent of the tardigrades resumed normal activity within forty-eight hours. The findings confirmed that tardigrades can survive conditions far more extreme than those encountered in any natural habitat on Earth.', $lyceon_json$[{"key":"A","text":"Tardigrades are able to endure extraordinarily harsh conditions by entering a reversible dormant state"},{"key":"B","text":"Tardigrades are popular subjects of study because their small size makes laboratory work convenient"},{"key":"C","text":"The University of Stuttgart has pioneered novel techniques for cooling biological specimens to near absolute zero"},{"key":"D","text":"Cryptobiosis is a metabolic strategy found across many phyla of microscopic organisms in extreme environments"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage focuses on how tardigrades survive extreme cold by entering cryptobiosis and resuming normal activity afterward. The choice stating that tardigrades endure harsh conditions through a reversible dormant state captures this central idea. The choice about laboratory convenience introduces a claim the passage never makes about why tardigrades are studied. The choice about the University of Stuttgart pioneering cooling techniques misidentifies the focus: the passage is about the organisms, not the university''s methods. The choice about cryptobiosis being found across many phyla extends beyond what the passage states, which discusses only tardigrades.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JVNSNZ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'The student wants to highlight the difference between male and female octopus dispersal behavior observed in the study. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L7U181', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "tempered" most nearly mean?', E'The ceramicist Luisa Montero was known for bold, unrestrained glazing techniques, but her later sculptures revealed an aesthetic that was markedly <u>tempered</u>. Clean lines replaced chaotic drips, and muted earth tones supplanted the electric blues and reds that had defined her earlier catalog.', $lyceon_json$[{"key":"A","text":"heated and then slowly cooled for durability"},{"key":"B","text":"angered to the point of visible frustration"},{"key":"C","text":"moderated and brought under careful restraint"},{"key":"D","text":"blended together from several incompatible sources"}]$lyceon_json$::jsonb, 'C', NULL, E'The passage contrasts Montero''s earlier "bold, unrestrained" style with later work featuring "clean lines" and "muted earth tones," indicating that her aesthetic became more controlled and restrained. The choice "moderated and brought under careful restraint" matches this shift from excess to discipline. The choice "heated and then slowly cooled for durability" invokes a metallurgical process unrelated to the artistic context here. The choice "angered to the point of visible frustration" relies on a colloquial meaning of "temper" that contradicts the calm, deliberate shift the passage describes. The choice "blended together from several incompatible sources" introduces an idea of mixing that the passage does not support — the change is toward simplicity, not combination.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LCD2FJ', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'The student wants to emphasize the design significance of the library''s facade. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MKU9O2', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The reforestation initiative led by conservationist Amara Diallo _______ resulted in the planting of over forty-seven thousand native hardwood seedlings across the degraded hillsides of the Fouta Djallon highlands.', $lyceon_json$[{"key":"A","text":"have"},{"key":"B","text":"are"},{"key":"C","text":"has"},{"key":"D","text":"were"}]$lyceon_json$::jsonb, 'C', NULL, E'The subject of the sentence is ''The reforestation initiative,'' a singular noun. The intervening prepositional phrase ''led by conservationist Amara Diallo'' does not change the number of the subject. A singular subject requires a singular verb form. The option ''has'' is the singular present-perfect form that agrees with ''initiative.'' The option ''have'' is plural and does not agree with the singular subject ''initiative.'' The options ''are'' and ''were'' are forms of ''to be'' that do not fit the sentence''s structure, which requires a helping verb for the past participle ''resulted.''', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NES921', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Entomologist Dr. Riya Chakravarti has spent over a decade studying the migration patterns of monarch butterflies in eastern North America. Her research has confirmed that monarchs rely on a combination of solar orientation and Earth''s magnetic field to navigate thousands of miles to their overwintering sites in central Mexico. ______ her team recently discovered that monarchs can recalibrate their internal compass when exposed to artificial magnetic fields, suggesting a level of navigational flexibility previously unrecognized in insects.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Additionally,"},{"key":"C","text":"By contrast,"},{"key":"D","text":"As a consequence of this flexibility,"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "Additionally," because the sentence following the blank introduces a new finding by Dr. Chakravarti''s team that adds to the information about monarch navigation already presented. The preceding sentence describes the known reliance on solar orientation and magnetic fields, and the next sentence presents an additional discovery about recalibration. "In other words," is incorrect because the second finding is not a restatement of the first. "By contrast," is incorrect because the new discovery does not contradict the earlier findings but rather extends them. "As a consequence of this flexibility," is incorrect because the recalibration ability is the discovery itself, not a consequence of something already described; moreover, the term "flexibility" appears after the blank, not before it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ON2VSU', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Lena Okafor has spent nearly a decade studying bioluminescent organisms in the Mariana _______ her research has revealed that certain deep-sea jellyfish produce light at wavelengths previously unrecorded in marine biology.', $lyceon_json$[{"key":"A","text":"Trench, her"},{"key":"B","text":"Trench her"},{"key":"C","text":"Trench; her"},{"key":"D","text":"Trench; and her"}]$lyceon_json$::jsonb, 'C', NULL, E'The blank separates two independent clauses: ''Marine biologist Lena Okafor has spent nearly a decade studying bioluminescent organisms in the Mariana Trench'' and ''her research has revealed that certain deep-sea jellyfish produce light at wavelengths previously unrecorded in marine biology.'' A semicolon correctly joins two independent clauses without a conjunction. The option using only a comma (''Trench, her'') creates a comma splice, which is non-standard. The option omitting all punctuation (''Trench her'') creates a run-on sentence. The option ''Trench; and her'' is redundant: a semicolon already functions as a clause separator equivalent to a period, so adding the conjunction ''and'' after it is non-standard — the correct pairing would be either a semicolon alone or a comma with a coordinating conjunction, not both.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OODA0L', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'The fruit bat Rousettus aegyptiacus is one of only a few bat species that uses echolocation produced by tongue clicking rather than laryngeal calls. <u>Unlike the sophisticated frequency-modulated pulses of insectivorous bats, the clicks of Rousettus are comparatively crude, each lasting only a fraction of a millisecond.</u> Nevertheless, these simple signals are sufficient to allow the bats to navigate through the pitch-dark caves where their colonies roost during daytime hours.', $lyceon_json$[{"key":"A","text":"It qualifies an earlier claim by noting a limitation of a particular trait"},{"key":"B","text":"It provides evidence that contradicts a hypothesis introduced in the first sentence"},{"key":"C","text":"It shifts the discussion from biology to physics by introducing acoustic terminology"},{"key":"D","text":"It establishes a problem that the rest of the passage then attempts to resolve"}]$lyceon_json$::jsonb, 'A', NULL, E'The first sentence introduces the fact that Rousettus uses tongue-click echolocation. The underlined sentence then qualifies that claim by noting the clicks are "comparatively crude" — acknowledging a limitation before the final sentence explains the clicks are still sufficient. The choice that describes qualifying an earlier claim by noting a limitation accurately captures this structure. The choice about contradicting a hypothesis is wrong because the underlined sentence does not dispute the first sentence; it adds nuance. The choice about shifting from biology to physics overstates the mention of acoustic details, which remain in a biological context. The choice about establishing a problem mischaracterizes the text''s structure: the passage does not present the crude clicks as a problem to be solved but rather as a qualified detail.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 55, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PVJZUL', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the overall structure of the text?', E'When the playwright Lorraine Hansberry completed her draft of The Sign in Sidney Brustein''s Window in 1964, critics expected a work that would extend the themes of racial injustice she had explored in A Raisin in the Sun. Instead, the play centered on a Jewish intellectual in Greenwich Village grappling with political disillusionment. Some reviewers dismissed the departure as a misstep, arguing that Hansberry had abandoned the subject matter that gave her voice its authority. Others, however, recognized that the play''s examination of idealism collapsing under the weight of compromise was itself a meditation on systemic injustice — one that operated through analogy rather than direct representation. Recent scholarship has largely vindicated the latter reading, situating the play within a broader tradition of mid-century American drama that used ostensibly apolitical settings to interrogate political failures indirectly.', $lyceon_json$[{"key":"A","text":"It introduces an expectation that was confounded, presents two contrasting critical responses, and indicates which response later scholarship has tended to support"},{"key":"B","text":"It summarizes the plot of a play, catalogs the negative reviews the play received at the time of its debut, and argues that those reviews relied on faulty aesthetic criteria"},{"key":"C","text":"It describes a playwright's career trajectory, compares two of her major works in thematic detail, and proposes that the later work surpasses the earlier one artistically"},{"key":"D","text":"It recounts a historical controversy surrounding a playwright, explains how the controversy was resolved during the playwright's lifetime, and draws a broader conclusion about mid-century American drama as a whole"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first establishes what critics expected from Hansberry, then presents two opposing reactions — dismissal and appreciation — and concludes by noting that recent scholarship has supported the appreciative reading. The choice describing an expectation confounded, two contrasting responses, and later scholarly support accurately mirrors this three-part structure. The choice about cataloging negative reviews and faulty aesthetic criteria misrepresents the passage, which presents both negative and positive reactions rather than only negative ones. The choice about comparing two works in thematic detail overstates the passage''s treatment of A Raisin in the Sun, which is mentioned only as a point of contrast, not analyzed thematically. The choice about resolution during the playwright''s lifetime is factually inconsistent with the passage, which attributes vindication to recent scholarship rather than to any resolution in Hansberry''s era.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R1LNZB', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'The student wants to present the study''s findings to an audience unfamiliar with the research while acknowledging the limitation Nandakumar identified. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RE8IS6', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1953, the psychologist Muzafer Sherif brought twenty-two eleven-year-old boys to a summer camp at Robbers Cave State Park in Oklahoma. He divided them into two groups that initially had no contact with each other, and each group quickly developed its own leadership hierarchy and group norms. When Sherif then arranged competitive activities between the groups, hostility escalated rapidly — the boys raided each other''s cabins and burned the opposing group''s flag. Only when Sherif introduced tasks requiring both groups to cooperate toward a shared goal, such as restoring the camp''s deliberately sabotaged water supply, did the intergroup animosity diminish.', $lyceon_json$[{"key":"A","text":"It describes a sequence of experimental phases and their escalating and then decreasing effects on participants"},{"key":"B","text":"It presents two competing theoretical frameworks and evaluates which better explains observed aggression"},{"key":"C","text":"It contrasts the researcher's original hypothesis with unexpected results that ultimately disproved it"},{"key":"D","text":"It chronicles the biographical development of a researcher through one formative professional experience"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage moves chronologically through three experimental phases — group formation, intergroup competition producing hostility, and cooperative tasks reducing that hostility — making the choice about describing experimental phases with escalating and then decreasing effects the accurate structural description. The choice about two competing theoretical frameworks is unsupported because the passage presents only one experiment, not competing theories. The choice about contrasting a hypothesis with unexpected results is wrong because the passage never states Sherif''s hypothesis or indicates the results were surprising. The choice about chronicling biographical development mischaracterizes the text, which focuses on the experiment''s design and outcomes rather than Sherif''s personal career trajectory.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TJR7ZQ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Physicist Tomoko Harada''s simulations of stellar nucleosynthesis in massive stars predict that silicon-28 should be produced in quantities roughly proportional to the star''s initial mass. Spectroscopic analyses of supernova remnants in the Cygnus Loop have largely confirmed this prediction, showing silicon-28 abundances that scale with estimated progenitor masses. ______ remnants from a 2021 survey of the Vela complex displayed silicon-28 levels nearly 40 percent below the values Harada''s models would predict for stars of comparable initial mass, a discrepancy her team attributes to the incomplete mixing of stellar layers during the explosion.', $lyceon_json$[{"key":"A","text":"For this reason,"},{"key":"B","text":"Similarly,"},{"key":"C","text":"That is,"},{"key":"D","text":"However,"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct transition is "However," because the sentence following the blank introduces a contrasting finding: the Vela complex remnants show silicon-28 levels significantly below what Harada''s models predict, whereas the preceding sentence states that the Cygnus Loop data largely confirmed the prediction. The relationship between these two findings is one of contrast. "For this reason," is incorrect because the Vela anomaly is not caused by the Cygnus Loop confirmation; the two are independent observations. "Similarly," is incorrect because the Vela data contradicts the prediction rather than supporting it in the way the Cygnus Loop data did. "That is," is incorrect because the sentence after the blank does not restate or clarify the preceding point but instead introduces a conflicting data set.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WAQ85F', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Economists studying municipal broadband networks have found that cities operating their own fiber-optic infrastructure tend to offer internet service at lower prices than private providers in the same regions. However, critics point out that municipal networks often rely on taxpayer-funded subsidies during their first decade of operation, raising questions about their true cost-effectiveness. A recent analysis by the Pew Research Center attempted to resolve this debate by calculating the total cost of ownership — including both direct subscriber fees and indirect taxpayer costs — for twenty-seven municipal networks that had been operating for at least fifteen years. The study found that in twenty-two of the twenty-seven cases, the total cost of ownership per household was lower for the municipal network than for comparable private service, suggesting that ________', $lyceon_json$[{"key":"A","text":"the initial subsidies are, in most instances, eventually offset by the sustained price advantages that municipal networks provide over time."},{"key":"B","text":"private internet providers deliberately inflate their prices in regions where municipal networks operate in order to recoup the revenue they have lost to publicly funded competition from city-owned infrastructure."},{"key":"C","text":"municipal broadband networks are uniformly more cost-effective than private alternatives regardless of the size or demographic composition of the cities they serve."},{"key":"D","text":"taxpayer subsidies for municipal networks should be increased to accelerate the timeline within which these networks achieve cost parity with private providers."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents a debate: municipal networks have lower prices but rely on subsidies. The Pew study found that total cost of ownership (fees plus taxpayer costs) was lower in twenty-two of twenty-seven cases after fifteen-plus years. The logical conclusion is that initial subsidies are eventually outweighed by sustained price advantages over time. The choice about private providers deliberately inflating prices introduces a motive the passage never discusses and is not supported by the data presented. The choice claiming uniform cost-effectiveness overstates the finding, since five of the twenty-seven cases did not show lower total cost of ownership. The choice recommending increased subsidies is a policy prescription that goes beyond what the data logically implies.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X80L2S', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'The Svalbard Global Seed Vault, carved into a mountainside on a Norwegian archipelago roughly 1,300 kilometers from the North Pole, stores duplicate samples of seeds from gene banks worldwide. Its permafrost location was chosen to keep the seeds frozen even without electrical refrigeration. <u>Yet in 2017, meltwater from unusually warm temperatures seeped into the entrance tunnel, prompting engineers to waterproof the structure and install drainage pumps that had not been part of the original design.</u> Proponents of the vault maintain that the core storage chambers remained well below freezing throughout the incident and that no seeds were damaged.', $lyceon_json$[{"key":"A","text":"It introduces a complication that complicates the reasoning presented in the preceding sentence"},{"key":"B","text":"It supplies statistical evidence quantifying the severity of climate change in the Arctic region"},{"key":"C","text":"It offers a rebuttal to the proponents mentioned later in the passage by proving the vault failed"},{"key":"D","text":"It provides background context that explains why the vault was originally constructed at that location"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence before the underlined one states the permafrost location was chosen to keep seeds frozen without refrigeration. The underlined sentence then introduces the 2017 meltwater incident, which complicates the assumption that permafrost alone would suffice — making the choice about introducing a complication to the preceding reasoning accurate. The choice about statistical evidence is wrong because the underlined sentence provides a narrative account of an event, not quantified data. The choice about offering a rebuttal overstates the underlined sentence''s force: it describes a challenge, but the final sentence notes that the core chambers remained safe, so the vault did not definitively fail. The choice about background context for why the vault was built is incorrect because the underlined sentence describes a later problem, not an original justification for the site selection.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZG29WO', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'In 2019, archaeologists excavating a Neolithic settlement near the banks of the Tisza River in southeastern Hungary unearthed a trove of ceramic vessels decorated with intricate geometric motifs. The patterns bore striking similarities to designs found at sites more than 400 kilometers away in present-day Serbia. ______ the researchers proposed that a network of trade routes connected these distant communities as early as 5200 BCE, facilitating not only the exchange of goods but also the diffusion of artistic traditions across the central Balkans.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"On the basis of these similarities,"},{"key":"C","text":"In spite of this evidence,"},{"key":"D","text":"Prior to this excavation, scholars had noted that"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct transition is "On the basis of these similarities," because the final sentence presents a conclusion (a proposed trade network) that the researchers drew from the evidence described in the preceding sentences, namely the similar motifs found at distant sites. The phrase logically connects the evidence to the inference. "Nevertheless," is incorrect because the researchers'' proposal does not run counter to the evidence about similar motifs; rather, it follows from that evidence. "In spite of this evidence," is incorrect for the same reason: the proposal is supported by the evidence, not offered despite it. "Prior to this excavation, scholars had noted that" is incorrect because it reframes the final sentence as a pre-existing scholarly view rather than a conclusion drawn from the newly excavated ceramics, misrepresenting the passage''s logic.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-18"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-18","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
